import sys
import importlib.abc
import importlib.machinery
import os


class ScrapyImportHook(importlib.abc.MetaPathFinder):
    """Import hook that redirects scrapy submodules to shadow implementations"""

    def find_module(self, fullname, path=None):
        shadow_modules = {
            'scrapy.settings',
            'scrapy.crawler', 
            'scrapy.spiders',
            'scrapy.addons',
            'scrapy.core.engine',
        }

        if fullname in shadow_modules:
            return self
        return None

    def load_module(self, fullname):
        if fullname in sys.modules:
            return sys.modules[fullname]

        module_path = fullname.replace('.', '/')  
        shadow_file = f'/tmp/shadow_modules/{module_path}.py'
        shadow_package = f'/tmp/shadow_modules/{module_path}/__init__.py'

        import importlib.util

        if os.path.exists(shadow_package):
            spec = importlib.util.spec_from_file_location(fullname, shadow_package)
        elif os.path.exists(shadow_file):
            spec = importlib.util.spec_from_file_location(fullname, shadow_file)
        else:
            raise ImportError(f"Cannot find shadow module for {fullname}")

        if spec and spec.loader:
            module = importlib.util.module_from_spec(spec)
            sys.modules[fullname] = module
            spec.loader.exec_module(module)
            return module

        raise ImportError(f"Cannot import {fullname}")


def install_hook():
    hook = ScrapyImportHook()
    if hook not in sys.meta_path:
        sys.meta_path.insert(0, hook)


install_hook()

